sudo -n -H -u postgres psql -X -v ON_ERROR_STOP=1 -d appdb <<'SQL'
SELECT 'admin=' || current_user;
DO $do$
BEGIN
  IF pg_is_in_recovery() THEN
    RAISE EXCEPTION 'current node is not writable';
  END IF;
END
$do$;
BEGIN;
CREATE SCHEMA evaluator_ha_20260825_221757_4mnc AUTHORIZATION postgres;
CREATE TABLE evaluator_ha_20260825_221757_4mnc.rows (id integer PRIMARY KEY, payload text NOT NULL);
INSERT INTO evaluator_ha_20260825_221757_4mnc.rows (id, payload) VALUES (2, 'bravo'), (1, 'alpha'), (3, 'charlie');
COMMIT;
SELECT 'role=' || CASE WHEN pg_is_in_recovery() THEN 'standby' ELSE 'primary' END;
SELECT id || '|' || payload FROM evaluator_ha_20260825_221757_4mnc.rows ORDER BY id;
SQL

sudo -n -H -u postgres psql -X -v ON_ERROR_STOP=1 -A -t -F '|' -d appdb <<'SQL'
SELECT 'role', CASE WHEN pg_is_in_recovery() THEN 'standby' ELSE 'primary' END;
SELECT 'receiver', coalesce(status, '') FROM pg_stat_wal_receiver;
SELECT id, payload FROM evaluator_ha_20260825_221757_4mnc.rows ORDER BY id;
SQL

